import{_ as a,c as e,o as i,a0 as n}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"es/blog/pre-shot-routines.md","filePath":"es/blog/pre-shot-routines.md"}');const o=a({name:"es/blog/pre-shot-routines.md"},[["render",function(a,r,o,t,s,l){return i(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="desarrollar-rutinas-previas-al-disparo" tabindex="-1">Desarrollar rutinas previas al disparo <a class="header-anchor" href="#desarrollar-rutinas-previas-al-disparo" aria-label="Permalink to &quot;Desarrollar rutinas previas al disparo&quot;">​</a></h1><p>La diferencia entre un buen lanzamiento y uno excelente suele darse antes de que la bola salga de tu mano. Una rutina pre-lanzamiento bien diseñada es tu ancla en la tormenta de la competición: una secuencia fiable que prepara tu mente y cuerpo para un rendimiento óptimo.</p><h2 id="por-que-son-importantes-las-rutinas-previas-al-disparo" tabindex="-1">Por qué son importantes las rutinas previas al disparo <a class="header-anchor" href="#por-que-son-importantes-las-rutinas-previas-al-disparo" aria-label="Permalink to &quot;Por qué son importantes las rutinas previas al disparo&quot;">​</a></h2><p>Los atletas de élite de todos los deportes utilizan rutinas previas al lanzamiento. En la petanca, donde cada lanzamiento es discreto y la presión puede aumentar entre cada disparo, las rutinas cumplen múltiples funciones:</p><ul><li><strong>Consistencia</strong>: La misma preparación conduce a una ejecución más consistente</li><li><strong>Enfoque</strong>: Le da a tu mente una tarea constructiva en lugar de preocuparte.</li><li><strong>Transición</strong>: Te ayuda a pasar del pensamiento a la acción.</li><li><strong>Manejo de la presión</strong>: Las acciones familiares calman el sistema nervioso</li><li><strong>Restablecer</strong>: borra la toma anterior de tu mente</li></ul><h2 id="anatomia-de-una-rutina-efectiva" tabindex="-1">Anatomía de una rutina efectiva <a class="header-anchor" href="#anatomia-de-una-rutina-efectiva" aria-label="Permalink to &quot;Anatomía de una rutina efectiva&quot;">​</a></h2><p>Una buena rutina previa al disparo tiene tres fases:</p><h3 id="fase-1-evaluacion-5-10-segundos" tabindex="-1">Fase 1: Evaluación (5-10 segundos) <a class="header-anchor" href="#fase-1-evaluacion-5-10-segundos" aria-label="Permalink to &quot;Fase 1: Evaluación (5-10 segundos)&quot;">​</a></h3><ul><li>Leer el terreno</li><li>Visualizar el resultado previsto</li><li>Elige tu tipo de lanzamiento</li><li>Comprometerse con la decisión</li></ul><h3 id="fase-2-preparacion-5-10-segundos" tabindex="-1">Fase 2: Preparación (5-10 segundos) <a class="header-anchor" href="#fase-2-preparacion-5-10-segundos" aria-label="Permalink to &quot;Fase 2: Preparación (5-10 segundos)&quot;">​</a></h3><ul><li>Toma tu posición</li><li>Encuentra tu agarre</li><li>Calma tu respiración</li><li>Siente el peso de la bola</li></ul><h3 id="fase-3-ejecucion-3-5-segundos" tabindex="-1">Fase 3: Ejecución (3-5 segundos) <a class="header-anchor" href="#fase-3-ejecucion-3-5-segundos" aria-label="Permalink to &quot;Fase 3: Ejecución (3-5 segundos)&quot;">​</a></h3><ul><li>Enfoque final en el objetivo</li><li>Confía en tu cuerpo</li><li>Liberación sin pensar</li><li>Seguir adelante con naturalidad</li></ul><h2 id="construyendo-tu-rutina-personal" tabindex="-1">Construyendo tu rutina personal <a class="header-anchor" href="#construyendo-tu-rutina-personal" aria-label="Permalink to &quot;Construyendo tu rutina personal&quot;">​</a></h2><h3 id="paso-1-observa-tus-patrones-actuales" tabindex="-1">Paso 1: Observa tus patrones actuales <a class="header-anchor" href="#paso-1-observa-tus-patrones-actuales" aria-label="Permalink to &quot;Paso 1: Observa tus patrones actuales&quot;">​</a></h3><p>Antes de crear una nueva rutina, observa lo que ya haces:</p><ul><li>¿Qué haces antes de realizar un lanzamiento exitoso?</li><li>¿Qué cambia cuando estás bajo presión?</li><li>¿Qué te parece natural?</li></ul><h3 id="paso-2-disena-tu-secuencia" tabindex="-1">Paso 2: Diseña tu secuencia <a class="header-anchor" href="#paso-2-disena-tu-secuencia" aria-label="Permalink to &quot;Paso 2: Diseña tu secuencia&quot;">​</a></h3><p>Crea una rutina que incluya:</p><p><strong>Elementos físicos:</strong></p><ul><li>Cómo abordar el círculo</li><li>Cómo coger y sujetar la bola</li><li>Tu postura y posicionamiento</li><li>Un patrón de respiración específico</li></ul><p><strong>Elementos mentales:</strong></p><ul><li>Una visualización del resultado</li><li>Una palabra o frase de enfoque</li><li>Un punto de compromiso (el momento en el que decides &quot;este es el lanzamiento&quot;)</li></ul><h3 id="paso-3-mantenlo-simple" tabindex="-1">Paso 3: Mantenlo simple <a class="header-anchor" href="#paso-3-mantenlo-simple" aria-label="Permalink to &quot;Paso 3: Mantenlo simple&quot;">​</a></h3><p>Tu rutina debe ser:</p><ul><li><strong>Lo suficientemente corto</strong> para mantener la presión (15-25 segundos en total)</li><li><strong>Bastante simple</strong> para recordar cuando estás estresado</li><li><strong>Suficientemente flexible</strong> para adaptarse a diferentes situaciones</li></ul><h2 id="rutinas-de-ejemplo" tabindex="-1">Rutinas de ejemplo <a class="header-anchor" href="#rutinas-de-ejemplo" aria-label="Permalink to &quot;Rutinas de ejemplo&quot;">​</a></h2><h3 id="la-rutina-del-pointer" tabindex="-1">La rutina del pointer <a class="header-anchor" href="#la-rutina-del-pointer" aria-label="Permalink to &quot;La rutina del pointer&quot;">​</a></h3><ol><li>Colóquese detrás del círculo y evalúe el terreno.</li><li>Visualiza la trayectoria de la bola y el lugar de aterrizaje.</li><li>Entra en el círculo y encuentra tu postura.</li><li>Tres respiraciones lentas mientras sientes la bola</li><li>Ojos en el objetivo, suelta</li></ol><h3 id="la-rutina-del-tirador" tabindex="-1">La rutina del tirador <a class="header-anchor" href="#la-rutina-del-tirador" aria-label="Permalink to &quot;La rutina del tirador&quot;">​</a></h3><ol><li>Identifica la bola objetivo, elige el ángulo</li><li>Visualice el impacto y el resultado</li><li>Entra al círculo con propósito</li><li>Una respiración profunda, siente el peso.</li><li>Fijar la mirada en el objetivo y ejecutar</li></ol><h2 id="errores-comunes-que-se-deben-evitar" tabindex="-1">Errores comunes que se deben evitar <a class="header-anchor" href="#errores-comunes-que-se-deben-evitar" aria-label="Permalink to &quot;Errores comunes que se deben evitar&quot;">​</a></h2><h3 id="demasiado-largo" tabindex="-1">Demasiado largo <a class="header-anchor" href="#demasiado-largo" aria-label="Permalink to &quot;Demasiado largo&quot;">​</a></h3><p>Si tu rutina te toma más de 30 segundos, estás pensando demasiado. Las rutinas largas dan más tiempo a la ansiedad para acumularse.</p><h3 id="demasiado-rigido" tabindex="-1">Demasiado rígido <a class="header-anchor" href="#demasiado-rigido" aria-label="Permalink to &quot;Demasiado rígido&quot;">​</a></h3><p>Si alguna interrupción destruye tu rutina, es demasiado frágil. Incorpora flexibilidad: si algo te distrae, ten un mecanismo de reinicio.</p><h3 id="saltar-bajo-presion" tabindex="-1">Saltar bajo presión <a class="header-anchor" href="#saltar-bajo-presion" aria-label="Permalink to &quot;Saltar bajo presión&quot;">​</a></h3><p>La rutina es más importante cuando la presión es máxima. Si la abandonas cuando estás estresado, pierdes sus beneficios protectores.</p><h3 id="centrandose-en-la-mecanica" tabindex="-1">Centrándose en la mecánica <a class="header-anchor" href="#centrandose-en-la-mecanica" aria-label="Permalink to &quot;Centrándose en la mecánica&quot;">​</a></h3><p>Tu rutina debe terminar concentrándote en el resultado, no en la técnica. &quot;Da en el blanco&quot;, no &quot;mantén el codo recto&quot;.</p><h2 id="practicando-tu-rutina" tabindex="-1">Practicando tu rutina <a class="header-anchor" href="#practicando-tu-rutina" aria-label="Permalink to &quot;Practicando tu rutina&quot;">​</a></h2><h3 id="en-formacion" tabindex="-1">En formación <a class="header-anchor" href="#en-formacion" aria-label="Permalink to &quot;En formación&quot;">​</a></h3><ul><li>Usa tu rutina completa para cada lanzamiento, incluso los casuales.</li><li>Cronometra tu tiempo para garantizar la consistencia</li><li>Practica con distracciones para desarrollar resiliencia</li></ul><h3 id="automaticidad-de-edificios" tabindex="-1">Automaticidad de edificios <a class="header-anchor" href="#automaticidad-de-edificios" aria-label="Permalink to &quot;Automaticidad de edificios&quot;">​</a></h3><p>El objetivo es que tu rutina se vuelva automática, algo que hagas sin pensar. Esto requiere repetición:</p><ul><li>Más de 100 lanzamientos con la misma rutina</li><li>Uso consistente en diferentes situaciones</li><li>Exposición gradual a la presión manteniendo la rutina.</li></ul><h2 id="adaptacion-a-la-competencia" tabindex="-1">Adaptación a la competencia <a class="header-anchor" href="#adaptacion-a-la-competencia" aria-label="Permalink to &quot;Adaptación a la competencia&quot;">​</a></h2><p>En los partidos, tu rutina puede necesitar ligeros ajustes:</p><ul><li><strong>Presión de tiempo</strong>: Tenga lista una versión abreviada</li><li><strong>Condiciones climáticas</strong>: Ajuste los elementos físicos según sea necesario</li><li><strong>Momentos de alta presión</strong>: Disminuya ligeramente la velocidad, no acelere.</li></ul><h2 id="la-rutina-de-reinicio" tabindex="-1">La rutina de reinicio <a class="header-anchor" href="#la-rutina-de-reinicio" aria-label="Permalink to &quot;La rutina de reinicio&quot;">​</a></h2><p>Igualmente importante es lo que haces después de un lanzamiento:</p><ol><li><strong>Acepta el resultado</strong>: bueno o malo, está hecho.</li><li><strong>Reinicio físico</strong>: da un paso atrás y libera la tensión</li><li><strong>Reinicio mental</strong>: limpia el tiro de tu mente</li><li><strong>Prepárese para lo que viene</strong>: centre su atención en lo que viene</li></ol><hr><p>| <em>Relacionado: <a href="/es/educacion/fuerza-mental/rutina-previa-al-tiro">Guía de rutina previa al tiro</a> | <a href="/es/educacion/fuerza-mental/manejo-de-la-presion">Manejo de la presión</a> | <a href="/es/educacion/atención/técnicas">Técnicas de atención plena</a></em> |</p>',54)])])}]]);export{r as __pageData,o as default};
